86	// Stub the remaining api calls used by renderWorkspaceDetail.
87	api.workspaces.get    = async () => ({ Id: 'DEV', id: 'DEV', Description: '', initialized: true, folderPath: '/tmp/dev' });
88	api.workspaces.health = async () => ({ healthy: true, issues: [] });
89	api.projects.get      = async () => ({ Id: 'my-project', Repositories: ['repo-alpha', 'repo-beta'] });
90	api.status.refresh    = async () => ({
91	    'repo-alpha': { currentBranch: 'main', localCommits: 0, unfetchedCommits: 0, modifiedFiles: 0, lastActivity: null, hasConflicts: false },
92	    'repo-beta':  { currentBranch: 'dev',  localCommits: 1, unfetchedCommits: 0, modifiedFiles: 2, lastActivity: null, hasConflicts: false },
93	});
94	api.status.get = api.status.refresh;
95	if (!api.config)          api.config          = {};
96	if (!api.config.polling)  api.config.polling  = {};
97	api.config.polling.get = async () => ({ gitPollingIntervalSeconds: 60 });
