101	// ---------------------------------------------------------------------------
102	// Render helper
103	// ---------------------------------------------------------------------------
104	
105	/**
106	 * Render the workspace detail view and wait for the async Promise.all inside
107	 * renderWorkspaceDetail to settle and populate the DOM.
108	 *
109	 * Returns both the container and the cleanup function so callers can stop
110	 * any pending interval.
111	 *
112	 * @param {string} [projectId]
113	 * @param {string} [wid]
114	 * @returns {Promise<{ container: HTMLElement, cleanup: function }>}
115	 */
116	async function renderView(projectId = 'my-project', wid = 'DEV') {
117	    const container = window.document.getElementById('app');
118	    container.innerHTML = '';
119	
120	    const cleanup = renderWorkspaceDetail(container, { id: projectId, wid });
121	
122	    // Wait for the internal async bootstrap to complete (Promise.all).
123	    // We poll until a <table> is present or a maximum wait is reached.
124	    await new Promise((resolve) => {
125	        let ticks = 0;
126	        const poll = () => {
127	            ticks++;
128	            if (container.querySelector('table') || ticks > 100) {
129	                resolve();
130	            } else {
131	                // Use the real (un-stubbed) Promise machinery to defer.
132	                Promise.resolve().then(poll);
133	            }
134	        };
135	        Promise.resolve().then(poll);
136	    });
137	
138	    return { container, cleanup };
139	}
