152	// ---------------------------------------------------------------------------
153	// Tests
154	// ---------------------------------------------------------------------------
155	
156	// AC 1 — 4th column header "Actions"
157	test('status table has a 4th column header labelled "Actions"', async () => {
158	    const { container, cleanup } = await renderView();
159	    try {
160	        const headers = container.querySelectorAll('thead th');
161	        assert.ok(headers.length >= 4, `expected ≥4 <th> elements, got ${headers.length}`);
162	        assert.equal(headers[3].textContent, 'Actions');
163	    } finally {
164	        cleanup();
165	    }
