168	// AC 2 — each row has a 4th cell with btn btn-secondary btn-sm
169	test('each repository row has a 4th cell with a correctly-styled "Open" button', async () => {
170	    const { container, cleanup } = await renderView();
171	    try {
172	        const rows = [...container.querySelectorAll('tbody tr[data-repo-id]')];
173	        assert.ok(rows.length > 0, 'expected at least one repository row');
174	
175	        for (const row of rows) {
176	            assert.ok(row.cells.length >= 4, `expected ≥4 cells, got ${row.cells.length}`);
177	            const btn = row.cells[3].querySelector('button');
178	            assert.ok(btn, 'expected a <button> in cells[3]');
179	            assert.equal(btn.textContent.trim(), 'Open');
180	            assert.ok(btn.classList.contains('btn'),           'missing class "btn"');
181	            assert.ok(btn.classList.contains('btn-secondary'), 'missing class "btn-secondary"');
182	            assert.ok(btn.classList.contains('btn-sm'),        'missing class "btn-sm"');
183	        }
184	    } finally {
185	        cleanup();
186	    }
187	});
