189	// AC 3 — clicking "Open" calls api.workspaces.launch.githubDesktop with correct args
190	test('clicking "Open" calls launch.githubDesktop with projectId, wid, and repoId', async () => {
191	    const { container, cleanup } = await renderView('my-project', 'DEV');
192	    try {
193	        const firstRow = container.querySelector('tbody tr[data-repo-id]');
194	        assert.ok(firstRow, 'expected at least one repository row');
195	
196	        const repoId = firstRow.dataset.repoId;
197	        const btn    = firstRow.cells[3].querySelector('button');
198	        btn.click();
199	
200	        // Drain microtask queue to let the async click handler run.
201	        await new Promise((r) => Promise.resolve().then(r));
202	        await new Promise((r) => Promise.resolve().then(r));
203	
204	        assert.equal(ghDesktopCalls.length, 1, 'expected exactly 1 launch.githubDesktop call');
205	        assert.equal(ghDesktopCalls[0].projectId, 'my-project');
206	        assert.equal(ghDesktopCalls[0].wid,       'DEV');
207	        assert.equal(ghDesktopCalls[0].repoId,    repoId);
208	    } finally {
209	        cleanup();
210	    }
211	});
212	
213	// AC 4 — on API failure the button is re-enabled (error path)
214	test('when launch.githubDesktop rejects, the button is re-enabled after the error', async () => {
215	    ghDesktopShouldFail  = true;
216	    ghDesktopFailMessage = 'app not installed';
217	
218	    const { container, cleanup } = await renderView();
219	    try {
220	        const firstRow = container.querySelector('tbody tr[data-repo-id]');
221	        const btn      = firstRow.cells[3].querySelector('button');
222	
223	        btn.click();
224	
225	        // Drain enough microtask ticks for try/catch/finally to complete.
226	        for (let i = 0; i < 10; i++) {
227	            await new Promise((r) => Promise.resolve().then(r));
228	        }
229	
230	        assert.equal(btn.disabled,           false,  'button should be re-enabled after error');
231	        assert.equal(btn.textContent.trim(), 'Open', 'button label should be restored after error');
232	        assert.equal(ghDesktopCalls.length,  1,      'API should have been called despite the error');
