  1	/**
  2	 * Toast Notification Component.
  3	 *
  4	 * Appends transient notification banners to the `#toast-container` element
  5	 * that already exists in index.html.  Each toast auto-dismisses after a
  6	 * configurable timeout with a CSS slide-out transition.  Multiple toasts
  7	 * stack vertically inside the container.
  8	 *
  9	 * CSS classes used: `toast`, `toast-success`, `toast-error`, `toast-info`,
 10	 * `toast-warning`, `toast.removing` — all defined in styles.css.
 11	 *
 12	 * Usage:
 13	 *   import { showToast } from './components/toast.js';
 14	 *
 15	 *   showToast('Repository saved.', 'success');
 16	 *   showToast('Something went wrong.', 'error');
 17	 *   showToast('Branch list refreshed.', 'info');
 18	 */
 19	
 20	// ---------------------------------------------------------------------------
 21	// Configuration
 22	// ---------------------------------------------------------------------------
 23	
 24	/** How long (ms) a toast stays visible before the slide-out animation runs. */
 25	const TOAST_DISPLAY_MS = 4_000;
 26	
 27	/** Duration (ms) of the CSS slide-out animation — must match styles.css. */
 28	const TOAST_ANIMATION_MS = 200;
 29	
 30	// ---------------------------------------------------------------------------
 31	// Internal helpers
 32	// ---------------------------------------------------------------------------
 33	
 34	/**
 35	 * Lazily retrieve (or create) the toast container element.
 36	 * Logs a warning if `#toast-container` is absent from the DOM.
 37	 *
 38	 * @returns {HTMLElement|null}
 39	 */
 40	function getContainer() {
 41	    const el = document.getElementById('toast-container');
 42	    if (!el) {
 43	        console.warn('[toast] #toast-container not found in the DOM. Toasts will not be displayed.');
 44	    }
 45	    return el;
 46	}
 47	
 48	/**
 49	 * Remove a toast element with a CSS slide-out transition, then detach it
 50	 * from the DOM.
 51	 *
 52	 * @param {HTMLElement} toastEl
 53	 */
 54	function dismissToast(toastEl) {
 55	    // Guard against double-dismiss (e.g., user click + auto-timer firing).
 56	    if (toastEl.dataset.dismissing === 'true') return;
 57	    toastEl.dataset.dismissing = 'true';
 58	
 59	    toastEl.classList.add('removing');
 60	
 61	    setTimeout(() => {
 62	        if (toastEl.parentNode) {
 63	            toastEl.parentNode.removeChild(toastEl);
 64	        }
 65	    }, TOAST_ANIMATION_MS);
 66	}
 67	
 68	// ---------------------------------------------------------------------------
 69	// Public export
 70	// ---------------------------------------------------------------------------
 71	
 72	/**
 73	 * Display a toast notification.
 74	 *
 75	 * @param {string} message            - Text to display inside the toast.  The
 76	 *   message is rendered via `textContent` (NOT `innerHTML`), so server-controlled
 77	 *   strings (including git error output) are safe to pass here — they will be
 78	 *   displayed as plain text and never interpreted as HTML.
 79	 * @param {'success'|'error'|'info'|'warning'} type - Visual variant.
 80	 * @param {number} [duration]         - Override the auto-dismiss delay in ms.
 81	 * @returns {HTMLElement|null}        - The created toast element, or null if
 82	 *   the container is unavailable.
 83	 */
 84	export function showToast(message, type, duration = TOAST_DISPLAY_MS) {
 85	    const VALID_TYPES = new Set(['success', 'error', 'info', 'warning']);
 86	    const safeType = VALID_TYPES.has(type) ? type : 'info';
 87	
 88	    const container = getContainer();
 89	    if (!container) return null;
 90	
 91	    // ------------------------------------------------------------------
 92	    // Build element
 93	    // ------------------------------------------------------------------
 94	    const toast = document.createElement('div');
 95	    toast.className = `toast toast-${safeType}`;
 96	    toast.setAttribute('role', 'status');
 97	    toast.setAttribute('aria-live', 'polite');
 98	
 99	    const text = document.createElement('span');
100	    text.className = 'toast-message';

101	    text.textContent = message;
102	
103	    // Close button for manual dismissal.
104	    const closeBtn = document.createElement('button');
105	    closeBtn.type = 'button';
106	    closeBtn.className = 'btn-icon toast-close';
107	    closeBtn.setAttribute('aria-label', 'Dismiss notification');
108	    closeBtn.textContent = '×';
109	
110	    toast.appendChild(text);
111	    toast.appendChild(closeBtn);
112	
113	    // ------------------------------------------------------------------
114	    // Mount
115	    // ------------------------------------------------------------------
116	    container.appendChild(toast);
117	
118	    // ------------------------------------------------------------------
119	    // Auto-dismiss
120	    // ------------------------------------------------------------------
121	    const timer = setTimeout(() => dismissToast(toast), duration);
122	
123	    closeBtn.addEventListener('click', () => {
124	        clearTimeout(timer);
125	        dismissToast(toast);
126	    });
127	
128	    return toast;
129	}

